<script lang="ts">
  import {onDestroy} from 'svelte';
  import {dismissDialog} from '../ui/dismiss-dialog';
  import type {ReferenceData} from '../data/reference';
  import {blankUma,type UmaBuild} from '../sandbox/model';
  import {withOwnUnique,nativeUnique,outfitUniques} from '../sandbox/editor';
  import {skillIconKey} from '../data/game-icons';
  import {statColors} from '../sandbox/stat-colors';
  import {mergeScreenshots,reviewSkillCandidates,statKeys,type ImportResult,type ScreenshotReading,type SkillChoice} from '../ocr/recognition';
  import {recognizeScreenshots,screenshotFile,screenshotLimit,type Screenshot} from '../ocr/worker';
  import GameIcon from './GameIcon.svelte';
  import UmaOutfitPicker from './UmaOutfitPicker.svelte';
  import ScreenshotImportIcon from './ScreenshotImportIcon.svelte';
  import {defaultAptitudes} from '../sandbox/aptitudes';
  export let reference:ReferenceData;
  export let onClose:()=>void;
  export let onImport:(uma:UmaBuild)=>void;
  export let visible=false;
  let dialog:HTMLDialogElement,generation=0;
  let images:Screenshot[]=[],selected=0,input:HTMLInputElement,error='',busy=false,adding=false,message='',fraction=0;
  let reviewQueries:Record<string,string>={};
  const reviewKey=(item:{image:number;text:string})=>`${item.image}:${item.text}`;
  function reviewChoices(item:{image:number;text:string;choices:SkillChoice[];nativeUnique?:boolean},query:string|undefined,cardId:number|null){return query!==undefined?reviewSkillCandidates(query,reference,cardId,item.nativeUnique):item.choices.length?item.choices:reviewSkillCandidates(item.text,reference,cardId,item.nativeUnique);}
  let readings:ScreenshotReading[]=[],result:ImportResult|null=null,ignored=new Set<number>(),controller:AbortController|undefined;
  const groups=[['Turf','Dirt'],['Sprint','Mile','Medium','Long'],['Front','Pace','Late','End']];
  $: valid=!!result?.cardId&&statKeys.every(k=>Number.isInteger(result?.stats[k])&&result!.stats[k]!>=1&&result!.stats[k]!<=2000);
  $: kept=result?.skills.filter(s=>!ignored.has(s.id))??[];
  $: if(dialog){if(visible&&!dialog.open)dialog.showModal();else if(!visible&&dialog.open)dialog.close();}
  onDestroy(()=>controller?.abort());
  function reset(){result=null;readings=[];reviewQueries={};ignored=new Set();message='';}
  export function clear(){generation++;controller?.abort();controller=undefined;busy=false;adding=false;images=[];selected=0;error='';fraction=0;reset();if(input)input.value='';}
  async function add(files:File[]){if(busy||adding)return;const epoch=generation;adding=true;error='';try{for(const file of files){if(images.length>=screenshotLimit)throw new Error(`Use up to ${screenshotLimit} screenshots per Uma.`);const image=await screenshotFile(file);if(epoch!==generation)return;if(!images.some(i=>i.id===image.id)){images=[...images,image];selected=images.length-1;reset();}}}catch(e){if(epoch===generation)error=e instanceof Error?e.message:String(e);}finally{if(epoch===generation){adding=false;if(input)input.value='';}}}
  function paste(e:ClipboardEvent){if(!visible)return;const files=Array.from(e.clipboardData?.files??[]).filter(f=>f.type.startsWith('image/'));if(files.length){e.preventDefault();e.stopPropagation();void add(files);}}
  function drop(e:DragEvent){e.preventDefault();e.stopPropagation();void add(Array.from(e.dataTransfer?.files??[]));}
  function remove(id:string){if(busy)return;images=images.filter(i=>i.id!==id);selected=Math.min(selected,Math.max(0,images.length-1));reset();}
  async function process(){if(!images.length||busy)return;const epoch=++generation;busy=true;error='';result=null;reviewQueries={};ignored=new Set();controller=new AbortController();
    try{const values=await recognizeScreenshots(images,reference,controller.signal,(value,text)=>{if(epoch===generation){fraction=value;message=text;}});if(epoch!==generation)return;readings=values;result=mergeScreenshots(readings,reference);message='';}
    catch(e){if(epoch===generation){if(e instanceof DOMException&&e.name==='AbortError')message='Cancelled';else error=e instanceof Error?e.message:String(e);}}
    finally{if(epoch===generation){busy=false;controller=undefined;}}
  }
  function chooseOutfit(cardId:number){const previous=result?.stats,next=mergeScreenshots(readings,reference,cardId);result={...next,stats:{...next.stats,...Object.fromEntries(statKeys.filter(k=>previous?.[k]!=null).map(k=>[k,previous![k]]))}};ignored=new Set();}
  function toggle(id:number){const next=new Set(ignored);if(next.has(id))next.delete(id);else next.add(id);ignored=next;}
  function resolve(index:number,choice:SkillChoice){
    if(!result)return;const item=result.unresolved[index];let cardId=result.cardId;
    if(item.nativeUnique&&!cardId){const owners=Object.keys(reference.metadata.outfits).map(Number).filter(id=>outfitUniques(reference,id).includes(choice.id));if(owners.length===1)cardId=owners[0];}
    const existing=result.skills.find(s=>s.id===choice.id),level=Number(item.text.match(/\bLv[l.]?\s*([1-6])\b/i)?.[1]??1);
    const skills=existing?result.skills.map(s=>s.id===choice.id?{...s,level:Math.max(s.level,level),sources:[...new Set([...s.sources,item.image])]}:s):[...result.skills,{id:choice.id,name:choice.name,level,sources:[item.image],confidence:choice.score}];
    result={...result,cardId,skills,unresolved:result.unresolved.filter((_,i)=>i!==index)};
  }
  function finish(){if(!result||!valid)return;const cardId=result.cardId!,aptitudes=defaultAptitudes(cardId),keys={Turf:'turf',Dirt:'dirt',Sprint:'short',Mile:'mile',Medium:'middle',Long:'long',Front:'front',Pace:'pace',Late:'late',End:'end'} as const;
    for(const [label,key] of Object.entries(keys)){const grade=result.aptitudes[label];if(grade&&/^[GFEDCBAS]$/.test(grade))aptitudes[key]=grade as typeof aptitudes[typeof key];}
    const value:UmaBuild={...blankUma(),cardId,charaId:Math.floor(cardId/100),name:reference.metadata.characters[Math.floor(cardId/100)]??'Imported Uma',stats:{...result.stats},aptitudes,skills:kept.map(s=>({id:s.id,level:s.level})),memo:''};
    onImport(withOwnUnique(value,reference));
  }
</script>
<svelte:window onpaste={paste}/>
<dialog bind:this={dialog} use:dismissDialog onclose={()=>{if(!dialog.open)onClose();}} ondrop={drop} ondragover={e=>{e.preventDefault();e.stopPropagation();}} ondragenter={e=>e.stopPropagation()} aria-label="Import Uma from Screenshots">
  <header><div><h2>Import Uma from Screenshots</h2><p>Paste (Ctrl+V), drop images, or choose files. Use screenshots of one Uma.</p></div><button class="icon-button" aria-label="Close screenshot import" onclick={onClose}>×</button></header>
  <input class="file-input" bind:this={input} type="file" accept="image/png,image/jpeg,image/webp" multiple onchange={e=>add(Array.from(e.currentTarget.files??[]))}/>
  <div class="import-body">
    <section class="screenshots" aria-label="Screenshot review">
      <div class="section-heading"><strong>Screenshots <small>{images.length} / {screenshotLimit}</small></strong><div class="image-actions"><button disabled={!images.length&&!busy&&!adding&&!result} onclick={clear}>Clear</button><button disabled={busy||adding} onclick={()=>input.click()}>＋ Add images</button></div></div>
      {#if images.length}
        <div class="preview"><img src={images[selected].url} alt={`Screenshot ${selected+1}: ${images[selected].name}`}/></div>
        <div class="image-list">{#each images as image,i (image.id)}<div class:chosen={i===selected}><button class="thumbnail" aria-label={`Review screenshot ${i+1}`} onclick={()=>selected=i}><img src={image.url} alt=""/><span>{i+1}</span></button><button class="remove" disabled={busy} aria-label={`Remove screenshot ${i+1}`} onclick={()=>remove(image.id)}>×</button></div>{/each}</div>
      {:else}<button class="empty-images" onclick={()=>input.click()}><span><ScreenshotImportIcon size={58}/></span>Add screenshots<small>Full pages, cropped lists, or individual skills</small></button>{/if}
      <small class="privacy">Processed locally · No image uploads</small>
    </section>
    <section class="recognition" aria-label="Recognized Uma">
      {#if error}<p class="error notice" role="alert">{error}</p>{/if}
      {#if busy}<div class="processing" role="status"><span class="spinner"></span><strong>{message}</strong><progress max="1" value={fraction}></progress></div>
      {:else if result}
        <UmaOutfitPicker {reference} cardId={result.cardId??0} onSelect={chooseOutfit}/>
        {#if !result.cardId}<p class="review-warning">Choose the Uma and outfit. They weren’t identified confidently.</p>{/if}
        {#each result.warnings as warning}<p class="review-warning">{warning}</p>{/each}
        <div class="stats">{#each statKeys as key}<label style={`--stat:${statColors[key]}`}><span><GameIcon name={`stat-${key}`} size={22}/>{key==='wisdom'?'Wit':key.charAt(0).toUpperCase()+key.slice(1)}</span><input type="number" min="1" max="2000" step="1" placeholder="Missing" aria-label={`Imported ${key}`} list={`ocr-stat-${key}`} bind:value={result.stats[key]}/><datalist id={`ocr-stat-${key}`}>{#each result.statChoices[key] as value}<option {value}></option>{/each}</datalist></label>{/each}</div>
        <details class="aptitudes"><summary>Captured aptitudes</summary>{#each groups as keys}<div>{#each keys as key}<label>{key}<select aria-label={`Captured ${key} aptitude`} bind:value={result.aptitudes[key]}><option value={undefined}>—</option><option value="?">?</option>{#each ['S','A','B','C','D','E','F','G'] as grade}<option value={grade}>{grade}</option>{/each}</select></label>{/each}</div>{/each}</details>
        <div class="section-heading skill-heading"><strong>Skills <small>{kept.length} unique skills</small></strong><button disabled={busy} onclick={process}>Read again</button></div>
        <div class="recognized-skills">{#each result.skills as skill (skill.id)}<div class:excluded={ignored.has(skill.id)}><input type="checkbox" aria-label={`Include ${skill.name}`} checked={!ignored.has(skill.id)} disabled={nativeUnique(reference.metadata.skills[skill.id])} onchange={()=>toggle(skill.id)}/><GameIcon name={skillIconKey(reference,skill.id)} size={24}/><span>{skill.name}<small title={skill.sources.map(i=>images[i].name).join('\n')}>{skill.sources.length===1?`Image ${skill.sources[0]+1}`:`${skill.sources.length} screenshots`}</small></span>{#if nativeUnique(reference.metadata.skills[skill.id])}<label>Lv<input type="number" min="1" max="6" aria-label={`${skill.name} imported level`} bind:value={skill.level}/></label>{/if}</div>{/each}{#if !result.skills.length}<p>No skill cards were read confidently. Add a clearer screenshot or add skills in the editor.</p>{/if}</div>
        {#if result.unresolved.length}<details class="unresolved" open><summary>Needs review <b>{result.unresolved.length}</b></summary>{#each result.unresolved as item,i}<div><button class="source-label" onclick={()=>selected=item.image}>Image {item.image+1} · {item.text}</button><input class="review-search" type="search" aria-label={`Find correct skill for Image ${item.image+1}: ${item.text}`} placeholder="Search for the correct skill…" value={reviewQueries[reviewKey(item)]??item.text} oninput={e=>reviewQueries={...reviewQueries,[reviewKey(item)]:e.currentTarget.value}}/><div class="suggestions">{#each reviewChoices(item,reviewQueries[reviewKey(item)],result.cardId) as choice}<button onclick={()=>resolve(i,choice)}>{choice.name}</button>{/each}<button class="skip" onclick={()=>{if(result)result={...result,unresolved:result.unresolved.filter((_,index)=>i!==index)};}} title="Skip this unrecognized text without adding a skill. The screenshot is kept.">Skip this text</button></div></div>{/each}</details>{/if}
      {:else}<div class="waiting"><span class="import-icons"><ScreenshotImportIcon size={64}/><span class="arrow">→</span><ScreenshotImportIcon kind="uma" size={60}/></span><h3>One Uma, send as many screenshots as you need.</h3><p>Stats and skills are merged across images. Repeated skills are added once.</p>{#if message}<p role="status">{message}</p>{/if}</div>{/if}
    </section>
  </div>
  <footer><span>{result?.unresolved.length?`${result.unresolved.length} unrecognized labels need review`:result?'Review the result before saving':''}</span><div><button onclick={onClose}>Cancel</button>{#if busy}<button onclick={()=>controller?.abort()}>Stop OCR</button>{:else if result}<button class="primary" disabled={!valid||!!result.unresolved.length} onclick={finish}>Review in editor →</button>{:else}<button class="primary" disabled={!images.length||adding} onclick={process}>Process {images.length||''} screenshot{images.length===1?'':'s'}</button>{/if}</div></footer>
</dialog>
<style>
  .review-search{display:block;width:100%;margin-top:5px;padding:7px 9px;font-size:12px}.image-actions{display:flex;gap:6px}
  .import-icons{display:flex;align-items:center;gap:22px}.import-icons .arrow{font-size:27px;color:var(--muted)}.waiting h3{max-width:390px;line-height:1.5}
  dialog{width:min(1520px,96vw);height:min(1120px,92dvh);max-height:92dvh;padding:0;border:1px solid var(--border);border-radius:12px;background:var(--panel);color:var(--text);box-shadow:var(--shadow)}dialog::backdrop{background:#0009}header,footer{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:16px 22px}header{border-bottom:1px solid var(--border)}header p{margin:7px 0 0;color:var(--muted);font-size:12px}header h2{margin:0;font-size:19px}header button{font-size:26px}.import-body{display:grid;grid-template-columns:minmax(270px,.85fr) minmax(470px,1.5fr);height:calc(100% - 155px);min-height:0}.screenshots,.recognition{min-width:0;padding:18px;overflow:auto}.screenshots{border-right:1px solid var(--border);background:var(--bg)}.section-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;font-size:14px}.section-heading small{font-size:11px;font-weight:400;margin-left:7px;color:var(--muted)}.section-heading button{font-size:11px}.preview{margin-top:14px;display:flex;justify-content:center;background:#080b0d;border:1px solid var(--border);height:clamp(220px,43dvh,570px);overflow:hidden;border-radius:7px}.preview img{width:100%;height:100%;object-fit:contain}.image-list{display:grid;grid-template-columns:repeat(4,1fr);gap:7px;margin-top:10px}.image-list>div{position:relative;min-width:0;border:1px solid var(--border);border-radius:5px;overflow:hidden}.image-list>div.chosen{border-color:var(--accent)}.thumbnail{position:relative;display:block;padding:0;width:100%;height:85px;background:var(--panel);border:0;border-radius:0}.thumbnail img{width:100%;height:100%;object-fit:contain}.thumbnail span{position:absolute;bottom:3px;left:4px;background:#000b;color:white;padding:1px 5px;border-radius:3px;font-size:10px}.remove{position:absolute;right:0;top:0;padding:0;width:20px;height:20px;background:#111d;color:white;border:0;border-radius:0;font-size:17px}.empty-images{display:flex;flex-direction:column;justify-content:center;gap:14px;width:100%;min-height:360px;border:1px dashed var(--muted);margin-top:15px;background:var(--panel);font-size:17px}.empty-images>span{font-size:50px;color:var(--accent)}.empty-images small{font-size:11px}.privacy{display:block;margin-top:12px;color:var(--muted);font-size:11px}.waiting,.processing{display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:420px;gap:15px;text-align:center}.waiting>span{font-size:45px;color:var(--accent)}.waiting h3{margin:0;font-size:18px}.waiting p{max-width:310px;font-size:13px;color:var(--muted);line-height:1.6}.processing strong{font-size:14px}.processing progress{width:80%;accent-color:var(--accent)}.spinner{width:32px;height:32px;border:3px solid var(--border);border-top-color:var(--accent);border-radius:50%;animation:spin .8s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}.stats{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:9px;margin:16px 0}.stats label{display:grid;gap:8px;min-width:0}.stats label>span{display:flex;align-items:center;gap:6px;color:var(--stat);font-size:12px}.stats input{width:100%;font-size:20px;font-weight:600;padding:9px 6px;border-bottom:2px solid var(--stat);font-variant-numeric:tabular-nums}.stats input::placeholder{font-size:12px}.aptitudes{margin:12px 0;font-size:12px}.aptitudes summary{cursor:pointer}.aptitudes>div{display:flex;gap:10px;margin-top:8px}.aptitudes label{display:flex;align-items:center;justify-content:space-between;gap:8px;flex:1;min-width:0;font-size:11px}.aptitudes select{padding:3px 5px}.skill-heading{margin-top:20px;border-top:1px solid var(--border);padding-top:15px}.recognized-skills{margin-top:10px;display:grid;grid-template-columns:1fr 1fr;gap:5px}.recognized-skills>div{display:flex;align-items:center;gap:7px;padding:8px;background:var(--bg);border:1px solid var(--border);border-radius:5px;min-width:0;font-size:12px}.recognized-skills>div>span{flex:1;min-width:0;overflow-wrap:anywhere}.recognized-skills small{display:block;font-size:10px;color:var(--muted);margin-top:3px}.recognized-skills label{display:flex;align-items:center;gap:4px;font-size:10px}.recognized-skills label input{width:42px;padding:4px}.excluded{opacity:.45}.recognized-skills p{font-size:12px;color:var(--muted);grid-column:1/-1}.review-warning{padding:9px 11px;border-left:2px solid #dfb65b;background:color-mix(in srgb,#dfb65b 7%,transparent);font-size:12px;line-height:1.5}.unresolved{margin-top:14px;padding:12px;border:1px solid #9c7b43;border-radius:6px}.unresolved summary{font-size:12px;cursor:pointer;color:#dfb65b}.unresolved b{margin-left:7px}.unresolved>div{padding-top:10px}.source-label{padding:3px 0;border:0;background:none;font-size:11px;color:var(--muted);white-space:normal;text-align:left}.suggestions{display:flex;flex-wrap:wrap;gap:5px;margin-top:4px}.suggestions button{padding:4px 7px;font-size:10px}.suggestions .skip{border-color:transparent;color:var(--muted)}footer{border-top:1px solid var(--border);min-height:65px}footer>span{font-size:11px;color:var(--muted)}footer>div{display:flex;gap:8px}@media(max-width:1000px){.import-body{grid-template-columns:290px minmax(0,1fr)}.recognized-skills{grid-template-columns:1fr}.stats label>span{font-size:10px}.stats input{font-size:16px}.stats{gap:5px}.image-list{grid-template-columns:repeat(3,1fr)}}
</style>
